// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /api/v1/admin/pedidos)
	ListarPedidos(ctx context.Context, request ListarPedidosRequestObject) (ListarPedidosResponseObject, error)

	// (GET /api/v1/admin/pedidos/{id})
	FichaDePedido(ctx context.Context, request FichaDePedidoRequestObject) (FichaDePedidoResponseObject, error)

	// (POST /api/v1/admin/pedidos/{id}/avanzar)
	AvanzarPedido(ctx context.Context, request AvanzarPedidoRequestObject) (AvanzarPedidoResponseObject, error)

	// (POST /api/v1/admin/pedidos/{id}/cancelar)
	CancelarPedido(ctx context.Context, request CancelarPedidoRequestObject) (CancelarPedidoResponseObject, error)
	// CobrarPedido Cobrar el pedido con su recibo (cobros.EmitirRecibo); el efectivo entra al turno de su sucursal
	// (POST /api/v1/admin/pedidos/{id}/cobro)
	CobrarPedido(ctx context.Context, request CobrarPedidoRequestObject) (CobrarPedidoResponseObject, error)
	// CorregirPedido Corrige los renglones y el flete de un pedido sin factura ni cobro; un precio bajo la lista pasado lo libre pide el PIN de un admin (422 en `pin`).
	// (POST /api/v1/admin/pedidos/{id}/correccion)
	CorregirPedido(ctx context.Context, request CorregirPedidoRequestObject) (CorregirPedidoResponseObject, error)
	// DevolverPedido La devolución de un pedido sin factura: baja lo que falta cobrar (o la cuenta corriente) y lo que vuelve al stock queda atado a ella. Con factura, se devuelve desde la factura.
	// (POST /api/v1/admin/pedidos/{id}/devolucion)
	DevolverPedido(ctx context.Context, request DevolverPedidoRequestObject) (DevolverPedidoResponseObject, error)

	// (PUT /api/v1/admin/pedidos/{id}/entrega)
	CambiarEntregaDelPedido(ctx context.Context, request CambiarEntregaDelPedidoRequestObject) (CambiarEntregaDelPedidoResponseObject, error)
	// UnirPedidoAFicha Ata un pedido sin cliente (y sin recibos ni comprobantes) a la ficha con el correo de su contacto
	// (POST /api/v1/admin/pedidos/{id}/ficha)
	UnirPedidoAFicha(ctx context.Context, request UnirPedidoAFichaRequestObject) (UnirPedidoAFichaResponseObject, error)
	// PedidoParaElTaller Lo que necesita el aserradero para cargar el corte de un pedido, sin importes ni datos de contacto
	// (GET /api/v1/admin/pedidos/{id}/taller)
	PedidoParaElTaller(ctx context.Context, request PedidoParaElTallerRequestObject) (PedidoParaElTallerResponseObject, error)

	// (GET /api/v1/admin/presupuestos)
	ListarPresupuestos(ctx context.Context, request ListarPresupuestosRequestObject) (ListarPresupuestosResponseObject, error)

	// (POST /api/v1/admin/presupuestos)
	CrearPresupuesto(ctx context.Context, request CrearPresupuestoRequestObject) (CrearPresupuestoResponseObject, error)

	// (GET /api/v1/admin/presupuestos/{id})
	FichaDePresupuesto(ctx context.Context, request FichaDePresupuestoRequestObject) (FichaDePresupuestoResponseObject, error)

	// (POST /api/v1/admin/presupuestos/{id}/estado)
	CambiarEstadoDePresupuesto(ctx context.Context, request CambiarEstadoDePresupuestoRequestObject) (CambiarEstadoDePresupuestoResponseObject, error)
	// UnirPresupuestoAFicha Ata un presupuesto sin cliente a la ficha con el correo de su contacto
	// (POST /api/v1/admin/presupuestos/{id}/ficha)
	UnirPresupuestoAFicha(ctx context.Context, request UnirPresupuestoAFichaRequestObject) (UnirPresupuestoAFichaResponseObject, error)

	// (POST /api/v1/admin/presupuestos/{id}/pedido)
	ConvertirPresupuestoEnPedido(ctx context.Context, request ConvertirPresupuestoEnPedidoRequestObject) (ConvertirPresupuestoEnPedidoResponseObject, error)

	// (GET /api/v1/presupuestos/{id}/pdf)
	PresupuestoPdf(ctx context.Context, request PresupuestoPdfRequestObject) (PresupuestoPdfResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

